      g.strokeStyle = "rgba(0,0,0,.12)"; g.lineWidth = 1;
      for (let k = 1; k < 16; k++) { g.beginPath(); g.moveTo(k * 28 + 0.5, 0); g.lineTo(k * 28 + 0.5, 448); g.moveTo(0, k * 28 + 0.5); g.lineTo(448, k * 28 + 0.5); g.stroke(); }
      drawCube(preview, current.faces);
