    const changed = () => { syncSame(); dirty = true; status.textContent = "Not saved yet"; draw(); };
    const setColour = (c) => { color = c; editor.querySelector(".colour").value = c; editor.querySelector(".current-colour").textContent = c; editor.querySelectorAll(".bd-swatches button").forEach((b) => b.classList.toggle("on", b.dataset.c === c)); };
    const setTool = (t) => { tool = t; editor.querySelectorAll(".tools button").forEach((b) => b.classList.toggle("on", b.dataset.tool === t)); };
    setColour(color); setTool(tool);

