    editor.querySelector(".rotate").onclick = () => { remember(); const d = faceData(); current.faces[face] = d.map((_, i) => { const x = i % 16, y = (i / 16) | 0; return d[(15 - x) * 16 + y]; }); changed(); };
    editor.querySelector(".clear").onclick = () => { remember(); current.faces[face] = EMPTY_FACE(); changed(); };
    editor.querySelector(".to-all").onclick = () => { remember(); const d = [...faceData()]; current.faces = { top: [...d], side: [...d], bottom: [...d] }; changed(); };
