    editor.querySelector(".bd-tabs").style.display = current.same ? "none" : "";
    see.onchange = () => { current.seeThrough = see.checked; dirty = true; };
    glow.onchange = () => { current.glows = glow.checked; dirty = true; };
    solid.onchange = () => { current.solid = solid.checked; dirty = true; };
