  g.fillStyle = "#3E8A30"; g.beginPath(); g.ellipse(200, 230, 120, 70, 0, 0, 7); g.fill();
  g.fillStyle = "#8A5A36"; g.fillRect(52, 120, 16, 50);
  g.fillStyle = "#2E7D32"; g.beginPath(); g.arc(60, 108, 32, 0, 7); g.fill();
  g.fillStyle = "#E94E4E"; g.fillRect(120, 130, 60, 46); g.fillStyle = "#7A2E2E"; g.beginPath(); g.moveTo(112, 132); g.lineTo(150, 100); g.lineTo(188, 132); g.fill();
