      g.strokeStyle = "rgba(0,0,0,.12)"; g.lineWidth = 1; g.beginPath();
      for (let x = x0; x <= x1; x++) { g.moveTo(ox + x * scale + 0.5, oy + y0 * scale); g.lineTo(ox + x * scale + 0.5, oy + y1 * scale); }
      for (let y = y0; y <= y1; y++) { g.moveTo(ox + x0 * scale, oy + y * scale + 0.5); g.lineTo(ox + x1 * scale, oy + y * scale + 0.5); }
