    if (e.code === "Space") { space = e.type === "keydown"; stage.style.cursor = space ? "grab" : "crosshair"; e.preventDefault(); }
    if (e.type === "keydown" && /^[0-9]$/.test(e.key)) { const n = (Number(e.key) || 10) - 1; if (n < palette.length) { pick = n; renderPalette(); draw(); } }
