document.head.appendChild(css);

// MARK: Puzzles

function solve(grid, count = false) {
  // Backtracking with the most-constrained cell first; counts solutions up to 2 when asked.
  let solutions = 0;
  const g = grid.slice();
  const options = (i) => {
    const r = (i / 9) | 0, c = i % 9, used = new Set();
    for (let k = 0; k < 9; k++) { used.add(g[r * 9 + k]); used.add(g[k * 9 + c]); }
    const br = r - (r % 3), bc = c - (c % 3);
    for (let y = 0; y < 3; y++) for (let x = 0; x < 3; x++) used.add(g[(br + y) * 9 + bc + x]);
    return [1, 2, 3, 4, 5, 6, 7, 8, 9].filter((n) => !used.has(n));
  };
  const go = () => {
    let best = -1, bestOpts = null;
    for (let i = 0; i < 81; i++) if (!g[i]) { const o = options(i); if (!bestOpts || o.length < bestOpts.length) { best = i; bestOpts = o; if (o.length <= 1) break; } }
    if (best < 0) { solutions++; return !count || solutions > 1; }
    const opts = count ? bestOpts : bestOpts.sort(() => Math.random() - 0.5);
    for (const n of opts) { g[best] = n; if (go()) return true; }
    g[best] = 0;
    return false;
  };
  go();
  return count ? solutions : g;
}

function generate(level) {
  const solution = solve(Array(81).fill(0));
  const puzzle = solution.slice();
  const order = [...Array(81).keys()].sort(() => Math.random() - 0.5);
  let clues = 81;
  for (const i of order) {
    if (clues <= LEVELS[level]) break;
    const keep = puzzle[i];
    puzzle[i] = 0;
    if (solve(puzzle, true) !== 1) puzzle[i] = keep; else clues--;
  }
  return { level, puzzle, solution, values: puzzle.slice(), notes: Array(81).fill(0), mistakes: 0, seconds: 0, hints: 0, started: new Date().toISOString() };
}

