let puzzle = await pac.storage.get("puzzle");
if (!puzzle) { puzzle = build(pickWords(22)); puzzle.title = "Everyday words"; await pac.storage.set("puzzle", puzzle); }
let sel = puzzle.solution.findIndex((c) => c), dir = "across";

const root = document.createElement("div");
root.className = "cw";
document.body.appendChild(root);
